type Order = {
  id: number;
  couponCode: string | null;
  // null = not known yet (address incomplete); 0 = free shipping
  shippingFeeCents: number | null;
};

function shippingLabel(order: Order): string {
  const fee = order.shippingFeeCents;
  if (fee === null) return 'Calculated at checkout';
  if (fee === 0) return 'Free';
  return `$${(fee / 100).toFixed(2)}`;
}

function usedCoupons(orders: Order[]): string[] {
  return orders.map((o) => o.couponCode).filter((c) => c !== null);
}

function couponBanner(order: Order, names: string[]): string[] {
  const code = order.couponCode;
  if (code === null) return [];
  return names.map((n) => `${n}, ${code.toUpperCase()} is applied`);
}

const orders: Order[] = [
  { id: 1001, couponCode: 'welcome10', shippingFeeCents: 0 },
  { id: 1002, couponCode: null, shippingFeeCents: null },
  { id: 1003, couponCode: 'loyal5', shippingFeeCents: 499 },
];
console.log(orders.map(shippingLabel), usedCoupons(orders));
